    auto details=new QFormLayout;header->addLayout(details,1);m_name=new QLineEdit(copy?source.name+" (2)":"");m_name->setObjectName("instanceName");details->addRow(t("Name"),m_name);m_group=new QComboBox;m_group->setEditable(true);m_group->setObjectName("instanceGroup");m_group->addItem(t("No group"),"");QSet<QString> groups;for(auto i:manager->instances()){try{auto g=ModRepository::read(i.dir+"/instance.json")["group"].toString();if(!g.isEmpty())groups.insert(g);}catch(...){}}for(auto g:groups)m_group->addItem(g,g);details->addRow(t("Group"),m_group);
    auto body=new QHBoxLayout;outer->addLayout(body,1);auto sources=new QListWidget;sources->setFixedWidth(158);sources->setObjectName("instanceSources");sources->addItems({t("Custom"),t("My packs"),t("Import"),"ATLauncher","CurseForge","FTB","FTB Legacy",t("Import FTB App"),"Modrinth","Technic"});sources->setCurrentRow(0);body->addWidget(sources);
    auto right=new QVBoxLayout;body->addLayout(right,1);m_status=new QLabel(t("Choose Minecraft, then a compatible mod loader."));m_status->setWordWrap(true);right->addWidget(m_status);
    auto gameArea=new QHBoxLayout;right->addLayout(gameArea,1);auto game=new QVBoxLayout;gameArea->addLayout(game,1);m_versions=new QTreeWidget;m_versions->setObjectName("minecraftVersions");m_versions->setColumnCount(3);m_versions->setHeaderLabels({t("Version"),t("Release date"),t("Type")});m_versions->setRootIsDecorated(false);m_versions->setSelectionMode(QAbstractItemView::SingleSelection);m_versions->header()->setSectionResizeMode(0,QHeaderView::Stretch);m_versions->header()->setSectionResizeMode(1,QHeaderView::ResizeToContents);m_versions->setMinimumHeight(160);game->addWidget(m_versions,1);m_search=new QLineEdit;m_search->setObjectName("versionSearch");m_search->setPlaceholderText(t("Search versions…"));game->addWidget(m_search);
    auto filters=new QVBoxLayout;gameArea->addLayout(filters);filters->addWidget(new QLabel(t("Filter")));for(auto entry:{qMakePair("release","Releases"),qMakePair("snapshot","Snapshots"),qMakePair("old_beta","Betas"),qMakePair("old_alpha","Alphas")}){auto c=new QCheckBox(t(entry.second));c->setObjectName(QString(entry.first)+"Filter");c->setChecked(QString(entry.first)=="release");m_types[entry.first]=c;filters->addWidget(c);connect(c,&QCheckBox::toggled,this,[this]{populateVersions();});}filters->addStretch();auto refresh=new QPushButton(t("Refresh"));filters->addWidget(refresh);connect(refresh,&QPushButton::clicked,this,[this]{m_status->setText(t("Checking versions…"));m_manager->fetchManifest();});
    auto loaderArea=new QHBoxLayout;right->addLayout(loaderArea,1);auto versions=new QVBoxLayout;loaderArea->addLayout(versions,1);m_loaderStatus=new QLabel;m_loaderStatus->setWordWrap(true);versions->addWidget(m_loaderStatus);m_loaders=new QListWidget;m_loaders->setObjectName("loaderVersions");m_loaders->setMinimumHeight(125);versions->addWidget(m_loaders,1);m_loaderSearch=new QLineEdit;m_loaderSearch->setPlaceholderText(t("Search loader versions…"));versions->addWidget(m_loaderSearch);connect(m_loaderSearch,&QLineEdit::textChanged,this,[this](QString query){for(int i=0;i<m_loaders->count();++i)m_loaders->item(i)->setHidden(!m_loaders->item(i)->text().contains(query,Qt::CaseInsensitive));});
    auto choices=new QVBoxLayout;loaderArea->addLayout(choices);choices->addWidget(new QLabel(t("Mod loader")));auto buttons=new QButtonGroup(this);for(auto kind:{"vanilla","neoforge","forge","fabric","quilt"}){auto key=QString(kind);auto title=key=="vanilla"?t("None"):key=="neoforge"?QString("NeoForge"):key.left(1).toUpper()+key.mid(1);auto radio=new QRadioButton(title);radio->setObjectName(key+"Loader");buttons->addButton(radio);choices->addWidget(radio);radio->setChecked(key=="vanilla");connect(radio,&QRadioButton::clicked,this,[this,key]{m_loader=key;fetchLoaders();});}choices->addStretch();auto reload=new QPushButton(t("Refresh"));choices->addWidget(reload);connect(reload,&QPushButton::clicked,this,[this]{fetchLoaders();});
    auto options=new QFormLayout;outer->addLayout(options);m_pack=new QComboBox;m_pack->setObjectName("initialPack");m_pack->addItem(t("No pack"));for(auto v:packs)m_pack->addItem(v.toObject()["name"].toString(),v.toObject());options->addRow(t("Initial pack"),m_pack);if(copy)m_pack->setEnabled(false);m_memory=new QSpinBox;m_memory->setRange(512,65536);m_memory->setSingleStep(512);m_memory->setValue(copy?source.xmx:4096);m_memory->setSuffix(" MB");options->addRow(t("Maximum memory"),m_memory);
    auto note=new QLabel(t("Java is detected automatically. Instances keep separate worlds, mods and settings."));note->setWordWrap(true);outer->addWidget(note);m_buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);m_buttons->button(QDialogButtonBox::Ok)->setText(t("Create instance"));outer->addWidget(m_buttons);connect(m_buttons,&QDialogButtonBox::accepted,this,[this]{validate();if(m_buttons->button(QDialogButtonBox::Ok)->isEnabled())accept();});connect(m_buttons,&QDialogButtonBox::rejected,this,&QDialog::reject);
