void CreateInstanceDialog::populateVersions(){
    auto selected=m_versions->currentItem()?m_versions->currentItem()->text(0):QString();QSignalBlocker block(m_versions);m_versions->clear();QTreeWidgetItem *keep=nullptr;for(auto v:m_catalog){if(!m_types.contains(v.type)||!m_types[v.type]->isChecked()||!v.id.contains(m_search->text(),Qt::CaseInsensitive))continue;auto item=new QTreeWidgetItem(m_versions,{v.id,v.releaseTime,Language::key(v.type=="release"?"Release":v.type=="snapshot"?"Snapshot":v.type=="old_beta"?"Beta":"Alpha")});if(v.id==selected)keep=item;}if(!keep&&m_versions->topLevelItemCount())keep=m_versions->topLevelItem(0);m_versions->setCurrentItem(keep);block.unblock();fetchLoaders();
}
void CreateInstanceDialog::fetchLoaders(){
    ++m_request;m_loading=false;m_loaders->clear();m_loaderSearch->clear();if(!m_versions->currentItem()){m_loaderStatus->setText(t("Choose a Minecraft version."));validate();return;}
    if(m_loader=="vanilla"){m_loaderStatus->setText(t("No mod loader selected. Vanilla uses the original game."));validate();return;}
    auto game=m_versions->currentItem()->text(0),loader=m_loader;int id=m_request;m_loading=true;m_loaderStatus->setText(t("Checking compatible loader versions…"));validate();auto watcher=new QFutureWatcher<QJsonObject>(this);
    connect(watcher,&QFutureWatcher<QJsonObject>::finished,this,[this,watcher,id]{auto result=watcher->result();watcher->deleteLater();if(id!=m_request)return;m_loading=false;if(result.contains("error")){m_loaderStatus->setText(result["error"].toString());validate();return;}for(auto v:result["versions"].toArray())m_loaders->addItem(v.toString());m_loaderStatus->setText(m_loaders->count()?t("Choose a loader version."):t("No compatible loader versions found."));if(m_loaders->count())m_loaders->setCurrentRow(0);validate();});
    watcher->setFuture(QtConcurrent::run([loader,game]{try{QJsonArray versions;for(auto v:Loaders::versions(loader,game))versions.append(v);return QJsonObject{{"versions",versions}};}catch(const std::exception &e){return QJsonObject{{"error",QString::fromUtf8(e.what())}};}}));
}
void CreateInstanceDialog::validate(){if(!m_buttons)return;m_buttons->button(QDialogButtonBox::Ok)->setEnabled(!m_name->text().trimmed().isEmpty()&&(!m_providerPack.isEmpty()||(m_versions->currentItem()&&!m_loading&&(m_loader=="vanilla"||m_loaders->currentItem()))));}
QJsonObject CreateInstanceDialog::configuration()const{return {{"name",m_name->text().trimmed()},{"mcVersion",m_versions->currentItem()?m_versions->currentItem()->text(0):QString()},{"providerPack",m_providerPack},{"providerVersion",m_providerVersion},{"loader",m_loader},{"loaderVersion",m_loaders->currentItem()?m_loaders->currentItem()->text():QString()},{"group",m_group->currentIndex()==0&&m_group->currentText()==t("No group")?QString():m_group->currentText().trimmed()},{"icon",m_icon->currentData().toString()},{"xmx",m_memory->value()},{"pack",m_pack->currentData().toJsonObject()}};}
